const getDepartmentTree = `-- name: GetDepartmentTree :many


WITH RECURSIVE department_tree AS (
  -- Root departments (no parent)
  SELECT 
    d.id,
    d.organization_id,
    d.name,
    d.description,
    d.parent_department_id,
    d.member_count,
    d.manager_count,
    d.child_count,
    d.updated_at,
    ARRAY[d.id] as path,
    0 as depth,
    d.name::TEXT as full_path
  FROM organization.department d
  WHERE d.organization_id = $1 AND d.parent_department_id IS NULL
  
  UNION ALL
  
  -- Child departments (recursive)
  SELECT 
    d.id,
    d.organization_id,
    d.name,
    d.description,
    d.parent_department_id,
    d.member_count,
    d.manager_count,
    d.child_count,
    d.updated_at,
    dt.path || d.id,
    dt.depth + 1,
    dt.full_path || ' > ' || d.name
  FROM organization.department d
  JOIN department_tree dt ON (d.organization_id, d.parent_department_id) = (dt.organization_id, dt.id)
  WHERE d.organization_id = $1
)
SELECT 
  dt.id,
  dt.organization_id,
  dt.name,
  dt.description,
  dt.parent_department_id,
  dt.member_count,
  dt.manager_count,
  dt.child_count,
  dt.updated_at,
  dt.path,
  dt.depth,
  dt.full_path
FROM department_tree dt
ORDER BY dt.path
`

