// =============================================================================
// Checks if target_parent is a descendant of department_to_move.
// Returns TRUE if moving would create a circular reference (invalid).
// Must be called BEFORE MoveDepartment to prevent circular references.
func (q *Queries) IsDepartmentDescendant(ctx context.Context, db DBTX, arg *IsDepartmentDescendantParams) (bool, error) {
	row := db.QueryRow(ctx, isDepartmentDescendant, arg.ID, arg.OrganizationID, arg.ID_2)
	var is_descendant bool
	err := row.Scan(&is_descendant)
	return is_descendant, err
}

const moveDepartment = `-- name: MoveDepartment :one
WITH old_dept AS (
  SELECT parent_department_id
  FROM organization.department
  WHERE id = $1 AND organization_id = $3
)
UPDATE organization.department
SET 
  parent_department_id = $2,
  updated_at = now()
FROM old_dept
WHERE department.id = $1
  AND department.organization_id = $3
RETURNING department.id, department.organization_id, department.name, department.description, department.parent_department_id, department.member_count, department.manager_count, department.child_count, department.updated_at, old_dept.parent_department_id AS old_parent_id
`

type MoveDepartmentParams struct {
	ID                 dbuuid.UUID     `json:"id"`
	ParentDepartmentID dbuuid.NullUUID `json:"parent_department_id"`
	OrganizationID     dbuuid.UUID     `json:"organization_id"`
}

type MoveDepartmentRow struct {
	ID                 dbuuid.UUID        `json:"id"`
	OrganizationID     dbuuid.UUID        `json:"organization_id"`
	Name               string             `json:"name"`
	Description        pgtype.Text        `json:"description"`
	ParentDepartmentID dbuuid.NullUUID    `json:"parent_department_id"`
	MemberCount        int32              `json:"member_count"`
	ManagerCount       int32              `json:"manager_count"`
	ChildCount         int32              `json:"child_count"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	OldParentID        dbuuid.NullUUID    `json:"old_parent_id"`
}

// Moves department to new parent (or root if NULL).
// Must run IsDepartmentDescendant check BEFORE calling this.
// Returns old parent_department_id in addition to updated row.
// NOTE: Application MUST:
//  1. Call DecrementDepartmentChildCount on old parent (if old parent exists)
//  2. Call IncrementDepartmentChildCount on new parent (if new parent exists)
func (q *Queries) MoveDepartment(ctx context.Context, db DBTX, arg *MoveDepartmentParams) (*MoveDepartmentRow, error) {
	row := db.QueryRow(ctx, moveDepartment, arg.ID, arg.ParentDepartmentID, arg.OrganizationID)
	var i MoveDepartmentRow
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Name,
		&i.Description,
		&i.ParentDepartmentID,
		&i.MemberCount,
		&i.ManagerCount,
		&i.ChildCount,
		&i.UpdatedAt,
		&i.OldParentID,
	)
	return &i, err
}

const removeEmployeeFromDepartment = `-- name: RemoveEmployeeFromDepartment :one
DELETE FROM organization.department_member
WHERE employee_id = $1
  AND organization_id = $2
RETURNING id, organization_id, department_id, employee_id, role, updated_at
`

type RemoveEmployeeFromDepartmentParams struct {
	EmployeeID     dbuuid.UUID `json:"employee_id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
}

// Removes employee from their current department.
// Returns the deleted row so application can update department counts.
// NOTE: Application MUST call DecrementDepartmentMemberCount after this.
func (q *Queries) RemoveEmployeeFromDepartment(ctx context.Context, db DBTX, arg *RemoveEmployeeFromDepartmentParams) (*OrganizationDepartmentMember, error) {
	row := db.QueryRow(ctx, removeEmployeeFromDepartment, arg.EmployeeID, arg.OrganizationID)
	var i OrganizationDepartmentMember
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.DepartmentID,
		&i.EmployeeID,
		&i.Role,
		&i.UpdatedAt,
	)
	return &i, err
}

const searchDepartments = `-- name: SearchDepartments :many
WITH search_config AS (
    SELECT set_limit(0.1) -- Lower threshold for short queries
)
SELECT 
    id,
    organization_id,
    name,
    description,
    member_count,
    parent_department_id,
    updated_at,
    similarity(name || ' ' || COALESCE(description, ''), $1) AS relevance_score
FROM organization.department
CROSS JOIN search_config
WHERE organization_id = $2
  AND (name || ' ' || COALESCE(description, '')) % $1
  AND ($3::uuid IS NULL OR id < $3::uuid)
ORDER BY relevance_score DESC, member_count DESC, id DESC
LIMIT $4::INT
`

type SearchDepartmentsParams struct {
	QueryText      string          `json:"query_text"`
	OrganizationID dbuuid.UUID     `json:"organization_id"`
	Cursor         dbuuid.NullUUID `json:"cursor"`
	Limit          int32           `json:"limit"`
}

type SearchDepartmentsRow struct {
	ID                 dbuuid.UUID        `json:"id"`
	OrganizationID     dbuuid.UUID        `json:"organization_id"`
	Name               string             `json:"name"`
	Description        pgtype.Text        `json:"description"`
	MemberCount        int32              `json:"member_count"`
	ParentDepartmentID dbuuid.NullUUID    `json:"parent_department_id"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	RelevanceScore     float32            `json:"relevance_score"`
}

// Fuzzy search for departments by name and description using trigram similarity.
// Uses lower similarity threshold (0.1) for better matching on short queries.
func (q *Queries) SearchDepartments(ctx context.Context, db DBTX, arg *SearchDepartmentsParams) ([]*SearchDepartmentsRow, error) {
	rows, err := db.Query(ctx, searchDepartments,
		arg.QueryText,
		arg.OrganizationID,
		arg.Cursor,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchDepartmentsRow
	for rows.Next() {
		var i SearchDepartmentsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.Name,
			&i.Description,
			&i.MemberCount,
			&i.ParentDepartmentID,
			&i.UpdatedAt,
			&i.RelevanceScore,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchEmployees = `-- name: SearchEmployees :many

WITH search_config AS (
    SELECT set_limit(0.1) -- Lower threshold for short queries
),
all_matches AS (
    -- Search by email
    SELECT 
        e.id,
        e.organization_id,
        e.given_name,
        e.family_name,
        e.is_active,
        e.updated_at,
        e.email,
        similarity(e.email, $3) AS relevance_score
    FROM organization.employee e
    CROSS JOIN search_config
    WHERE e.organization_id = $4
      AND e.is_active = true
      AND e.email % $3
    
    UNION ALL
    
    -- Search by given name
    SELECT 
        e.id,
        e.organization_id,
        e.given_name,
        e.family_name,
        e.is_active,
        e.updated_at,
        e.email,
        similarity(e.given_name, $3) AS relevance_score
    FROM organization.employee e
    CROSS JOIN search_config
    WHERE e.organization_id = $4
      AND e.is_active = true
      AND e.given_name % $3
    
    UNION ALL
    
    -- Search by family name
    SELECT 
        e.id,
        e.organization_id,
        e.given_name,
        e.family_name,
        e.is_active,
        e.updated_at,
        e.email,
        similarity(e.family_name, $3) AS relevance_score
    FROM organization.employee e
    CROSS JOIN search_config
    WHERE e.organization_id = $4
      AND e.is_active = true
      AND e.family_name % $3
)
SELECT 
    id,
    organization_id,
    given_name,
    family_name,
    is_active,
    updated_at,
    email,
    MAX(relevance_score)::float4 AS relevance_score
FROM all_matches
WHERE ($1::uuid IS NULL OR id < $1::uuid)
GROUP BY id, organization_id, given_name, family_name, is_active, updated_at, email
ORDER BY MAX(relevance_score) DESC, updated_at DESC, id DESC
LIMIT $2::INT
`

type SearchEmployeesParams struct {
	Cursor         dbuuid.NullUUID `json:"cursor"`
	Limit          int32           `json:"limit"`
	QueryText      string          `json:"query_text"`
	OrganizationID dbuuid.UUID     `json:"organization_id"`
}

type SearchEmployeesRow struct {
	ID             dbuuid.UUID        `json:"id"`
	OrganizationID dbuuid.UUID        `json:"organization_id"`
	GivenName      string             `json:"given_name"`
	FamilyName     string             `json:"family_name"`
	IsActive       bool               `json:"is_active"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	Email          string             `json:"email"`
	RelevanceScore float32            `json:"relevance_score"`
}

// =============================================================================
// SEARCH QUERIES (Multilingual Fuzzy Search with pg_trgm)
// =============================================================================
// Strategy: Use separate indexes for each field, UNION results in single query, group by ID
// Database handles deduplication and keeps best relevance score per employee
// Fuzzy search for employees across email, given_name, and family_name fields.
// Uses UNION ALL to search each field with its dedicated index, then groups by employee ID.
// Keeps the maximum relevance score when an employee matches multiple fields.
func (q *Queries) SearchEmployees(ctx context.Context, db DBTX, arg *SearchEmployeesParams) ([]*SearchEmployeesRow, error) {
	rows, err := db.Query(ctx, searchEmployees,
		arg.Cursor,
		arg.Limit,
		arg.QueryText,
		arg.OrganizationID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchEmployeesRow
	for rows.Next() {
		var i SearchEmployeesRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.GivenName,
			&i.FamilyName,
			&i.IsActive,
			&i.UpdatedAt,
			&i.Email,
			&i.RelevanceScore,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setDepartmentManager = `-- name: SetDepartmentManager :one
UPDATE organization.department_member
SET 
  role = 'manager',
  updated_at = now()
WHERE department_id = $1
  AND employee_id = $2
  AND organization_id = $3
  AND role != 'manager'  -- Only update if not already manager
RETURNING id, organization_id, department_id, employee_id, role, updated_at
`

type SetDepartmentManagerParams struct {
	DepartmentID   dbuuid.UUID `json:"department_id"`
	EmployeeID     dbuuid.UUID `json:"employee_id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
}

// Updates employee role to 'manager' in their department.
// Employee must already be a member of the department.
// NOTE: Application MUST call AdjustDepartmentManagerCount(delta=+1) after this if role changed.
func (q *Queries) SetDepartmentManager(ctx context.Context, db DBTX, arg *SetDepartmentManagerParams) (*OrganizationDepartmentMember, error) {
	row := db.QueryRow(ctx, setDepartmentManager, arg.DepartmentID, arg.EmployeeID, arg.OrganizationID)
	var i OrganizationDepartmentMember
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.DepartmentID,
		&i.EmployeeID,
		&i.Role,
		&i.UpdatedAt,
	)
	return &i, err
}

const updateDepartment = `-- name: UpdateDepartment :one
UPDATE organization.department
SET 
  name = COALESCE($3, name),
  description = COALESCE($4, description),
  updated_at = now()
WHERE id = $1 
  AND organization_id = $2
RETURNING id, organization_id, name, description, parent_department_id, member_count, manager_count, child_count, updated_at
`

type UpdateDepartmentParams struct {
	ID             dbuuid.UUID `json:"id"`
	OrganizationID dbuuid.UUID `json:"organization_id"`
	Name           string      `json:"name"`
	Description    pgtype.Text `json:"description"`
}

// Updates department name and/or description.
func (q *Queries) UpdateDepartment(ctx context.Context, db DBTX, arg *UpdateDepartmentParams) (*OrganizationDepartment, error) {
	row := db.QueryRow(ctx, updateDepartment,
		arg.ID,
		arg.OrganizationID,
		arg.Name,
		arg.Description,
	)
	var i OrganizationDepartment
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Name,
		&i.Description,
		&i.ParentDepartmentID,
		&i.MemberCount,
		&i.ManagerCount,
		&i.ChildCount,
		&i.UpdatedAt,
	)
	return &i, err
}
